exercises.solution:
def terdekat(titik, target):
    if not titik:
        return None
    def kuadrat_jarak(p):
        return sum((x - y) ** 2 for x, y in zip(p, target))
    return min(range(len(titik)), key=lambda i: kuadrat_jarak(titik[i]))

